#[local] Notation "'u'" := bv_unsigned (only parsing).

(* [comment removed for export] *)
Lemma gv_col : forall k regs m (typ e w j line : Z),
  (typ = 4 \/ typ = 5)%Z -> gev_ok typ e -> (0 <= j < w)%Z -> Z.of_nat k = (w - j)%Z -> (w < 2 ^ 31)%Z ->
  (0 <= line)%Z -> (line + w + 4 < 2 ^ 64)%Z ->
  (forall q, (j <= q < w)%Z -> exists b : byte, m (Z_to_bv 64 (xor3 (line + q))) = Some b) ->
  getr regs 11 = Z_to_bv 64 typ -> getr regs 13 = Z_to_bv 64 e -> getr regs 6 = Z_to_bv 64 (line + j) -> getr regs 17 = Z_to_bv 64 j ->
  getr regs 15 = Z_to_bv 64 w -> getr regs 21 = Z_to_bv 64 1 -> getr regs 16 = Z_to_bv 64 1 ->
  exists regs' (e' : Z),
    msteps SEGS (mkst regs (0x1dc88 : word) m al_rom) (mkst regs' (0x1dc58 : word) m al_rom)
    /\ getr regs' 5 = Z_to_bv 64 e' /\ getr regs' 13 = Z_to_bv 64 e' /\ (0 <= e' <= 255)%Z
    /\ regs_agree (fun x => In x [5; 6; 7; 13; 17; 28; 29]%list) regs regs'.
