(* [comment removed for export] *)
Lemma gv_rows : forall k regs m (typ e w h i data wpl : Z),
  (typ = 4 \/ typ = 5)%Z -> gev_ok typ e -> (0 <= i < h)%Z -> Z.of_nat k = (h - i)%Z -> (h < 2 ^ 31)%Z -> (1 <= w < 2 ^ 31)%Z ->
  (0 <= wpl)%Z -> (w <= 4 * wpl)%Z -> (data mod 4 = 0)%Z -> (0 <= data)%Z -> (data + 4 * (wpl * h) + 8 <= 2 ^ 64)%Z ->
  (forall a, (data <= a < data + 4 * (wpl * h))%Z -> exists b : byte, m (Z_to_bv 64 a) = Some b) ->
  getr regs 11 = Z_to_bv 64 typ -> getr regs 13 = Z_to_bv 64 e -> getr regs 8 = Z_to_bv 64 (data + 4 * wpl * i) -> getr regs 14 = Z_to_bv 64 i ->
  getr regs 12 = Z_to_bv 64 h -> getr regs 15 = Z_to_bv 64 w -> getr regs 10 = Z_to_bv 64 (4 * wpl) -> getr regs 21 = Z_to_bv 64 1 -> getr regs 16 = Z_to_bv 64 1 ->
  exists regs' (e' : Z),
    msteps SEGS (mkst regs (0x1dc68 : word) m al_rom) (mkst regs' (0x1dde0 : word) m al_rom)
    /\ getr regs' 5 = Z_to_bv 64 e' /\ (0 <= e' <= 255)%Z
